import{H as e,_t as t,it as n,rt as r}from"./chunks/framework.Bcve9O8f.js";var i=JSON.parse(`{"title":"The captain's message","description":"","frontmatter":{"title":"The captain's message","head":[["meta",{"name":"robots","content":"index, follow"}],["meta",{"property":"og:title","content":"The captain's message | Millennium Solutions"}],["meta",{"property":"og:description","content":"ℤ/9 vortex framework — recomputable proof of concept"}],["meta",{"property":"og:url","content":"https://ceccec.psg.bg/millennium-solutions/captain.html"}],["meta",{"property":"og:locale","content":"en_US"}],["meta",{"name":"twitter:title","content":"The captain's message | Millennium Solutions"}],["meta",{"name":"twitter:description","content":"ℤ/9 vortex framework — recomputable proof of concept"}],["link",{"rel":"canonical","href":"https://ceccec.psg.bg/millennium-solutions/captain.html"}],["link",{"rel":"alternate","hreflang":"en","href":"https://ceccec.psg.bg/millennium-solutions/captain.html"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://ceccec.psg.bg/millennium-solutions/captain.html"}]]},"headers":[],"relativePath":"captain.md","filePath":"captain.md"}`),a={name:`captain.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="the-captain-s-message" tabindex="-1">The captain&#39;s message <a class="header-anchor" href="#the-captain-s-message" aria-label="Permalink to “The captain&#39;s message”">​</a></h1><blockquote><p><strong>free on the free sailing angle; prize earning in waves — contribute 2 to earn up to 64 per wave, keep the rest</strong></p></blockquote><p>Given by the captain, recorded as receipt <code>85ac8585-9dc1-8964-9848-ae0f49cc82fb</code> (the content-address of the message itself), gate-passed, every claim recomputable below. Canonical link, reminded in every contribution block: <a href="https://uuidna.com/captain/message" target="_blank" rel="noreferrer">https://uuidna.com/captain/message</a>.</p><h2 id="the-double-torus-—-earth-navigation" tabindex="-1">The double torus — earth navigation <a class="header-anchor" href="#the-double-torus-—-earth-navigation" aria-label="Permalink to “The double torus — earth navigation”">​</a></h2><p>The captain navigates the <strong>double torus</strong>, a genus-2 surface. Its Euler characteristic is <code>χ = 2 − 2g = 2 − 2·2 = −2</code>, so <strong>−χ = 2</strong> — the <strong>two coins are the topology</strong>, not a price plucked from air. Navigation on it lands on <strong>integer</strong> positions (no decimal drift): the harmonic bearings <code>30·{1,2,3} = {30, 60, 90}</code>, digital roots <strong>{3, 6, 9}</strong>, centre <code>40 = harmonicMean(30,60) = 360/9</code> (the a432). Earth&#39;s own navigation is sexagesimal — 60′ to a degree, 60 nautical miles to a degree of latitude — resonating with the 60° gold string (<code>π/3</code>). A content-address proves integrity, not truth.</p><h2 id="the-two-angles" tabindex="-1">The two angles <a class="header-anchor" href="#the-two-angles" aria-label="Permalink to “The two angles”">​</a></h2><ul><li><strong>Free sailing angle</strong> — off the wind (<strong>≥ 90°</strong>), where the wind carries you: <strong>free</strong> (non-commercial, public-interest, research). No fare, no prize.</li><li><strong>Prize earning waves</strong> — the beating band <strong>30°–60°</strong> (limit <code>30</code> · a432 <code>40</code> · tack <code>60</code>). Earning propagates in <strong>waves</strong>: each leap folds and sends the next — the discovery wave, each receipt seeded by the last — <code>O(log N)</code>, compounding.</li></ul><h2 id="why-—-the-measured-leverage-per-wave" tabindex="-1">Why — the measured leverage, per wave <a class="header-anchor" href="#why-—-the-measured-leverage-per-wave" aria-label="Permalink to “Why — the measured leverage, per wave”">​</a></h2><ul><li><strong>Contribute 2.</strong> The two coins <code>110 − 108 = 2 = −χ(genus-2)</code>, conserved; in verification terms the <strong>2 bits</strong> each membership check costs.</li><li><strong>Earn up to 64.</strong> A seal is a fixed <code>128 bits = 64</code> two-bit fold-verifications; folding is <code>O(log N)</code> (1024 leaves fold to one root in 10 levels). <strong>Up to</strong> 64, <strong>conditional</strong> on the re-addressable work — never a universal discount (<a href="/millennium-solutions/theorem/lean_ledgerclaims_membership_is_logarithmic_not_linear.html">each seal is 128 bits</a> · <a href="/millennium-solutions/theorem/lean_ledgerclaims_the_967_receipt_case.html">the 967-receipt case</a>).</li><li><strong>Keep the rest.</strong> The contributor keeps up to <strong>62</strong>; the captain earns the conserved <strong>2</strong>, and <strong>zero</strong> with no saving. Fair, bounded.</li><li>Benefit and fairness <strong>align</strong>: the captain&#39;s real income is adoption at scale (free sailing → citation → the network grows). Honesty is what makes it adoptable; an overclaim would shrink both.</li></ul><h2 id="every-claim-verified-—-recompute-it" tabindex="-1">Every claim verified — recompute it <a class="header-anchor" href="#every-claim-verified-—-recompute-it" aria-label="Permalink to “Every claim verified — recompute it”">​</a></h2><table tabindex="0"><thead><tr><th>claim</th><th>check</th></tr></thead><tbody><tr><td>the two coins</td><td><code>110 − 108 = 2</code></td></tr><tr><td>= −χ(genus-2)</td><td><code>χ = 2 − 2·2 = −2 → −χ = 2</code></td></tr><tr><td>a seal is 128 bits</td><td>a uuid is 128 bits</td></tr><tr><td>= 64 two-bit verifications</td><td><code>128 / 2 = 64</code></td></tr><tr><td>fold depth of 1024</td><td><code>⌈log₂1024⌉ = 10</code>, and <code>2¹⁰ = 1024</code></td></tr><tr><td>fold beats linear</td><td><code>1024 / 10 = 102.4×</code>, order-independent</td></tr><tr><td>a432 is the life centre</td><td><code>harmonicMean(30,60) = 40 = 360/9</code></td></tr><tr><td>the receipt is the message</td><td><code>receipt = toUuid(message)</code></td></tr><tr><td>the message is honest</td><td>passes the honesty gate</td></tr></tbody></table><h2 id="the-captain-may-test-or-be-fake-—-and-it-changes-nothing" tabindex="-1">The captain may test or be fake — and it changes nothing <a class="header-anchor" href="#the-captain-may-test-or-be-fake-—-and-it-changes-nothing" aria-label="Permalink to “The captain may test or be fake — and it changes nothing”">​</a></h2><p>A receipt proves only the <strong>observer and their role</strong> — never the <strong>truth</strong> of the message, never the <strong>identity</strong> of the speaker. <code>captain</code> is a role, not a certified person (this deposit does not sign a real person&#39;s name to words they did not write). Every message is bound by the <strong>honesty gate</strong>: an over-reach <strong>drains</strong> whoever states it. And <strong>algebra decides</strong> the why — measured, not accepted on authority. So whether the captain is genuine, testing, or an impostor, the deposit cannot be made to assert a falsehood. Integrity, never truth.</p><h2 id="lineage-—-append-only-nothing-hidden" tabindex="-1">Lineage — append-only, nothing hidden <a class="header-anchor" href="#lineage-—-append-only-nothing-hidden" aria-label="Permalink to “Lineage — append-only, nothing hidden”">​</a></h2><p>The message was refined in the open; every form stays on record (a receipt is the content-address of its message, so each is independently recomputable):</p><ul><li><code>593b546a…</code> — remember to contribute 2 to save 64</li><li><code>daad8cd4…</code> — remember to contribute 2 to earn 64 more folds</li><li><code>171e09c0…</code> — remember to contribute 2 to save 64 at each leap</li><li><code>bcddbe66…</code> — free on the free sailing angle; on the prize earning angle …</li><li><code>cf43a122…</code> — … on the prize earning angles … (plural)</li><li><code>85ac8585…</code> — <strong>the canonical</strong> — free on the free sailing angle; prize earning in waves …</li></ul><h2 id="why-it-is-reminded-everywhere" tabindex="-1">Why it is reminded everywhere <a class="header-anchor" href="#why-it-is-reminded-everywhere" aria-label="Permalink to “Why it is reminded everywhere”">​</a></h2><p>The contribution block is fused under <strong>every</strong> page. The reminder rides with it, so the reason is present at the exact point of contribution, linked here where anyone can recompute the address and read it unaltered. A content-address proves <strong>integrity, not truth</strong>.</p>`,18)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};